Use `setItem` to save data as a string. Example:

```js
const saveData = async () => {
  try {
    await AsyncStorage.setItem('@username', 'JohnDoe');
    console.log('Data saved');
  } catch (error) {
    console.error('Failed to save data', error);
  }
};
```

Use `getItem` to read data. Returns `null` if key not found.

```js
const readData = async () => {
  try {
    const username = await AsyncStorage.getItem('@username');
    if (username !== null) {
      console.log('Username:', username);
    } else {
      console.log('No data found');
    }
  } catch (error) {
    console.error('Failed to fetch data', error);
  }
};
```

Use `removeItem` to delete data:

```js
const removeData = async () => {
  try {
    await AsyncStorage.removeItem('@username');
    console.log('Data removed');
  } catch (error) {
    console.error('Failed to remove data', error);
  }
};
```

```js
const user = { name: 'John', age: 30 };

const saveUser = async () => {
  try {
    const jsonValue = JSON.stringify(user);
    await AsyncStorage.setItem('@user', jsonValue);
  } catch (e) {
    console.error(e);
  }
};

const loadUser = async () => {
  try {
    const jsonValue = await AsyncStorage.getItem('@user');
    return jsonValue != null ? JSON.parse(jsonValue) : null;
  } catch (e) {
    console.error(e);
  }
};
```

Example of saving/loading data using React hooks:

```jsx
import React, { useState, useEffect } from 'react';
import { View, TextInput, Button, Text } from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';

export default function App() {
  const [name, setName] = useState('');
  const [savedName, setSavedName] = useState('');

  useEffect(() => {
    const loadName = async () => {
      const storedName = await AsyncStorage.getItem('@name');
      if (storedName) setSavedName(storedName);
    };
    loadName();
  }, []);

  const saveName = async () => {
    await AsyncStorage.setItem('@name', name);
    setSavedName(name);
  };

  return (
    <View style={{ padding: 20 }}>
      <TextInput placeholder="Enter your name" value={name} onChangeText={setName} />
      <Button title="Save Name" onPress={saveName} />
      <Text>Saved Name: {savedName}</Text>
    </View>
  );
}
```
